using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class SnapshotOriginalOrderNative {
 static bool slow;static readonly object gate=new object();static void Send(object o){lock(gate)Console.WriteLine(new JavaScriptSerializer{MaxJsonLength=16777216}.Serialize(o));}
 static void Put(string p,string s){Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,s,new UTF8Encoding(false));}
 public static int Main(string[] args){LauncherRuntime.Initialize();Console.InputEncoding=Console.OutputEncoding=new UTF8Encoding(false);string root=Path.GetFullPath(args[0]),game=Path.Combine(root,"steamapps/common/ProjectZomboid"),user=Path.Combine(root,"用户"),data=Path.Combine(root,"data"),save=Path.Combine(user,"Saves/Sandbox/Original/mods.txt");
 Put(Path.Combine(game,"ProjectZomboid64.exe"),"never executed isolated fixture");Put(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(game,"game-version.txt"),"42.21.0");Put(Path.Combine(game,"version.txt"),"42.21.0");Put(Path.Combine(game,"media/payload.bin"),"independent game bytes");
 string mods="VERSION = 1,\r\nmods\r\n{\r\n mod = B,\r\n mod = A,\r\n}\r\nmaps\r\n{\r\n}\r\n";Put(save,mods);Put(Path.Combine(user,"mods/default.txt"),mods);foreach(string id in new[]{"A","B"})Put(Path.Combine(user,"mods",id,"42/mod.info"),"id="+id+"\nname="+id+"\n"+(id=="B"?"require=A\n":"incompatible=B\n"));
 using(var c=new ModernController(game,user,data,true)){c.Event=(name,o)=>{Send(new{ev=name,data=o});if(slow&&name=="environmentProgress"){slow=false;Thread.Sleep(500);}};c.Progress=(v,t)=>Send(new{ev="progress",data=new{value=v,text=t}});c.Execute("environmentStorageSave",new Dictionary<string,object>{{"directory",Path.Combine(root,"中文快照")}});Send(new{ready=true,root=root,game=game,user=user,save=save});var jobs=new List<Task>();string line;while((line=Console.ReadLine())!=null){string raw=line;jobs.Add(Task.Run(()=>{object id=null;try{var r=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(raw);id=r["id"];string a=(string)r["action"];var p=(Dictionary<string,object>)r["payload"];object result;if(a=="fixtureSlow"){slow=true;result=new{delayed=true};}else if(a=="fixtureBad"){Put(save,"invalid fixture syntax");result=new{changed=true};}else if(a=="fixtureRestore"){Put(save,mods);result=new{changed=true};}else if(a.StartsWith("environment")||a=="cancel")result=c.Execute(a,p);else throw new IOException("Unsupported fixture action");Send(new{id=id,ok=true,data=result});}catch(Exception e){Send(new{id=id,ok=false,error=e.Message});}}));}Task.WaitAll(jobs.ToArray());}return 0;
 }}}
